import{readOwnedLabPose,ownedLabWorld}from'../development/lab-interior/lab-scene.mjs';
const authorities=new WeakMap(),grants=new WeakMap();
export const LAB_EVENTS=Object.freeze(['P01_ECO_CENTER','P02_FIRST_PARTNER','P03_TUTORIAL']);
const rows=Object.freeze({P01_ECO_CENTER:[10,11,'거제 생태센터에서 윤 박사를 만나고 최근 야생 생태몬이 평소와 다르게 움직인다는 이야기를 듣는다.'],P02_FIRST_PARTNER:[15,11,'첫 생태친구를 선택한다.'],P03_TUTORIAL:[20,11,'이동·조사·NPC 대화·첫 야생전·포획을 자연스럽게 익힌다.']});
const event=id=>typeof id==='string'&&id.startsWith('event:')&&LAB_EVENTS.includes(id.slice(6))?id.slice(6):null;
export function isLabRequest(id,a){return !!event(id)&&a&&Object.getPrototypeOf(a)===Object.prototype&&Reflect.ownKeys(a).length===1&&Object.getOwnPropertyDescriptor(a,'type')?.value==='event'}
export function createLabAuthority({getWorld,getScene,getSignal}={}){if([getWorld,getScene,getSignal].some(x=>typeof x!=='function'))throw Error('LAB_PRIVATE_OWNER_REQUIRED');const a=Object.freeze({});authorities.set(a,{getWorld,getScene,getSignal});return a}
export const isLabAuthority=a=>authorities.has(a);
function read(a,w,id){const o=authorities.get(a),e=event(id);if(!o||o.getWorld()!==w||!e)return null;const scene=o.getScene(),p=readOwnedLabPose(scene);if(!p||ownedLabWorld(scene)!==w||p.disposed||p.moving||!p.focused||p.reader||p.pending||p.facing!=='up'||Math.abs(p.foot[0]-470)+Math.abs(p.foot[1]-345)>24)return null;const s=w.snapshot(),r=w.definition.points[id],v=rows[e];if(s.position.scene!=='world:hub:PROLOGUE'||s.world.mapId!==s.position.scene||s.progress.currentStage!=='PROLOGUE'||s.enhancedLeague?.phase==='active'||r?.id!==id||Reflect.ownKeys(r).length!==11||r.kind!=='event'||r.mapId!==s.position.scene||r.stageId!=='PROLOGUE'||r.areaId!==null||r.x!==v[0]||r.y!==v[1]||r.label!==v[2]||r.eventId!==e||r.npcId!=='NPC_CHAMPION_DOCTOR_YOON'||r.placementStatus!=='DEV_PLACEMENT_NOT_FINAL_GEOGRAPHY')return null;const next=LAB_EVENTS.find(x=>!w.story.eventCompleted(x)&&w.story.eventAvailable(x));if(next!==e)return null;return{scene,position:JSON.stringify(p),runtime:JSON.stringify({sessionId:s.sessionId,revision:s.revision,starterId:s.starterId,party:s.party,progress:s.progress,position:s.position})}}
export function mintLabGrant(a,w,id){const p=read(a,w,id),o=authorities.get(a),signal=o?.getSignal();if(!p||!(signal instanceof AbortSignal)||signal.aborted)throw Error('LAB_EVENT_UNAVAILABLE');const g=Object.freeze({});grants.set(g,{a,w,id,p,signal});return g}
export function assertLabGrant(g,w){const q=grants.get(g),o=q&&authorities.get(q.a),p=q&&read(q.a,w,q.id);if(!q||q.w!==w||!p||p.scene!==q.p.scene||p.position!==q.p.position||p.runtime!==q.p.runtime||q.signal.aborted||o.getSignal()!==q.signal)throw Error('LAB_EVENT_OWNER_DRIFT')}
export function labGrantSignal(g,w){assertLabGrant(g,w);return grants.get(g).signal}
export function revokeLabGrant(g){grants.delete(g)}
